21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String lastName = owner.getLastName();
24	        String postcode = owner.getPostcode();
25	        String telephone = owner.getTelephone();
26	
27	        Owner match = null;
28	        if (postcode != null) {
29	            for (Owner existing : ownerRepository.findAll()) {
30	                if (postcode.equals(existing.getPostcode())
31	                        && equalsIgnoreCase(lastName, existing.getLastName())
32	                        && !equals(telephone, existing.getTelephone())) {
33	                    if (match == null || existing.getId() < match.getId()) {
34	                        match = existing;
35	                    }
36	                }
37	            }
38	        }
39	
