11	    /** The maximum level assignable at creation; level 4 is reserved for tenure. */
12	    public static final int MAX = 3;
13	
14	    private MembershipLevel() {
15	    }
16	
17	    /** The membership level for the given owner. */
18	    public static int of(Owner owner) {
19	        int level = 1;
20	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
21	            level++;
22	        }
23	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
24	            level++;
25	        }
26	        return Math.min(level, MAX);
27	    }
28	}
